def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    own = []
    opp = []
    opp_d = 0
    for me, op in history:
        own.append(me)
        opp.append(op)
        if op == 'D':
            opp_d += 1

    last_me, last_opp = history[-1]

    streak = 0
    for op in reversed(opp):
        if op == 'D':
            streak += 1
        else:
            break

    recent_d = sum(1 for op in opp[-10:] if op == 'D')

    if opp_d == 0 and n >= 30:
        confirmed = False
        for i in range(n - 1):
            if own[i] == 'D' and own[i + 1] == 'C' and opp[i + 1] == 'C':
                confirmed = True
                break
        if confirmed:
            return 'D'
        if last_me == 'D':
            return 'C'
        return 'D'

    if last_opp == 'D':
        if opp_d == n:
            return 'D'
        if n >= 10 and opp_d * 2 >= n:
            return 'D'
        if streak >= 3:
            return 'D'
        if recent_d >= 4:
            return 'D'

        if n >= 2 and own[-2] == 'D':
            if streak >= 2 and (opp_d * 3 >= n or recent_d >= 2):
                return 'D'
            if rng.random() < 0.85:
                return 'C'
            return 'D'

        if streak == 1 and n >= 20 and opp_d <= max(1, n // 10):
            if rng.random() < 0.5:
                return 'C'
            return 'D'

        return 'D'

    return 'C'
